#!/usr/bin/env bash
# CANONICAL SOURCE: github.com/Pbash-js/lakebase-accelerator -> scripts/deploy_db.sh
# Do NOT edit this file in a copy. Change it here, then propagate to consumers.
#
# Lakebase branch deploy: mint OAuth credential -> migrations -> objects -> tests.
#
# Branch safety (hard rule): branch_test.sh NEVER targets production from a
# developer terminal. Interactive runs deploy to a personal dev branch —
# created off production (7-day TTL) if it doesn't exist. Production is
# reachable ONLY inside GitHub Actions CD (cd-promotion, GITHUB_ACTIONS=true
# and TARGET_BRANCH=production set by the workflow).
#
# Env vars: LAKEBASE_PROJECT and DATABRICKS_PG_USER are prompted for when
# missing in an interactive session; CI must set them (hard fail otherwise).
#
# Auth: local `databricks auth login` profile, or DATABRICKS_HOST + DATABRICKS_TOKEN in CI.
set -euo pipefail
. "$(dirname "$0")/lib.sh"

# one-time setup: scripts/init_project.sh writes .env.local (project + role)
[ -f "$(dirname "$0")/../.env.local" ] && . "$(dirname "$0")/../.env.local"
if [ -z "${LAKEBASE_PROJECT:-}" ] && [ ! -f "$(dirname "$0")/../.env.local" ]; then
  echo "▶ first run - one-time setup:"
  ./scripts/init_project.sh
  . "$(dirname "$0")/../.env.local"
fi

INTERACTIVE=0
if [ -t 0 ]; then INTERACTIVE=1; fi

# --- branch resolution ------------------------------------------------------
if [ -n "${TARGET_BRANCH:-}" ]; then
  if [ "$TARGET_BRANCH" = "production" ] && [ "${GITHUB_ACTIONS:-}" != "true" ]; then
    echo "✗ refusing to deploy to production outside GitHub Actions CD." >&2
    echo "  Production deploys happen only via cd-promotion (merge to main)." >&2
    echo "  Locally, run without TARGET_BRANCH to deploy to a dev branch." >&2
    exit 1
  fi
else
  if [ "$INTERACTIVE" != 1 ]; then
    echo "✗ TARGET_BRANCH not set in a non-interactive session — CI must set it explicitly." >&2
    exit 1
  fi
  _DEFAULT="dev-$(whoami | tr '[:upper:]' '[:lower:]' | tr -cd 'a-z0-9' | cut -c1-12)-$(date +%Y%m%d)"
  read -r -p "Target branch [${_DEFAULT}]: " _TB || _TB=""
  TARGET_BRANCH="${_TB:-$_DEFAULT}"
fi
if ! [[ "$TARGET_BRANCH" =~ ^[a-z][a-z0-9-]{0,62}$ ]]; then
  echo "Invalid branch id '$TARGET_BRANCH': 1-63 chars, lowercase start, lowercase/numbers/hyphens" >&2; exit 1
fi

# --- env vars: prompt interactively, fail hard in CI -----------------------
if [ -z "${LAKEBASE_PROJECT:-}" ]; then
  if [ "$INTERACTIVE" = 1 ]; then
    read -r -p "Lakebase project id (e.g. core-app-db): " LAKEBASE_PROJECT
  fi
  : "${LAKEBASE_PROJECT:?set LAKEBASE_PROJECT (the Lakebase project id, e.g. from databricks.yml)}"
fi
if [ -z "${DATABRICKS_PG_USER:-}" ]; then
  if [ "$INTERACTIVE" = 1 ]; then
    read -r -p "Lakebase Postgres role (e.g. your email): " DATABRICKS_PG_USER
  fi
  : "${DATABRICKS_PG_USER:?set DATABRICKS_PG_USER (your Lakebase Postgres role, e.g. your email)}"
fi

# --- preflight: fail fast with actionable messages, before touching anything
PREFLIGHT_FAIL=0
if ! databricks current-user me -o json >/dev/null 2>&1; then
  echo "✗ Databricks CLI not authenticated — run: databricks auth login"
  PREFLIGHT_FAIL=1
fi
[ "$PREFLIGHT_FAIL" = 0 ] || exit 1
echo "✓ preflight ok (authed via CLI; project: $LAKEBASE_PROJECT)"

trap 'echo "❌ deploy failed (line $LINENO). If auth was the problem: databricks auth login. If the token expired: re-run." >&2' ERR

# --- dev branch: create off production (7-day TTL) if absent, wait ACTIVE --
# (skipped for CD's production target)
if [ "$TARGET_BRANCH" != "production" ]; then
  if databricks postgres get-branch "projects/${LAKEBASE_PROJECT}/branches/${TARGET_BRANCH}" -o json >/dev/null 2>&1; then
    echo "▶ branch ${TARGET_BRANCH} already exists — reusing"
  else
    echo "▶ creating dev branch ${TARGET_BRANCH} off production (7-day TTL)"
    lb_create_branch "$LAKEBASE_PROJECT" "$TARGET_BRANCH" production 604800
  fi
  lb_wait_endpoint "projects/${LAKEBASE_PROJECT}/branches/${TARGET_BRANCH}/endpoints/primary" \
    || { echo "Endpoint did not become ready in time" >&2; exit 1; }
fi

ENDPOINT="projects/${LAKEBASE_PROJECT}/branches/${TARGET_BRANCH}/endpoints/primary"
echo "▶ target: $TARGET_BRANCH  (project: $LAKEBASE_PROJECT)"
HOST="$(lb_host "$ENDPOINT")"
TOKEN="$(lb_token "$ENDPOINT")"
echo "::add-mask::${TOKEN}"   # never leak the runtime credential in logs

cd "$(dirname "$0")/.."

# --- Pro declarative inner loop ---------------------------------------------
# Local Pro runs (GITHUB_ACTIONS unset) converge the branch to the FULL
# desired state (db/schema + db/objects) with ONE `atlas schema apply`:
# schema changes test without generating a migration first; the migration is
# only frozen (gen_migration.sh) before the PR. CI/CD never take this path
# (GITHUB_ACTIONS=true): the rehearsal must exercise the versioned artifacts,
# and production must never be declaratively drifted to desired state.
if [ "${ATLAS_EDITION:-ce}" = "pro" ] && [ "${GITHUB_ACTIONS:-}" != "true" ]; then
  ATLAS_BIN="${ATLAS_BIN:-atlas}"
  command -v "$ATLAS_BIN" >/dev/null 2>&1 || { echo "✗ atlas CLI not found (set ATLAS_BIN)"; exit 1; }
  echo "▶ Pro declarative: schema apply (db/schema + db/objects -> ${TARGET_BRANCH})"
  DESIRED=".tmp_pro/desired_deploy.sql"
  python scripts/build_desired.py --out "$DESIRED" >/dev/null
  SCRATCH="atlas_dev_$$"
  ENC_USER="$(python -c "import urllib.parse;print(urllib.parse.quote('${DATABRICKS_PG_USER}', safe=''))")"
  APP_URL="postgres://${ENC_USER}:${TOKEN}@${HOST}:5432/databricks_postgres?sslmode=require"
  DEV_URL="postgres://${ENC_USER}:${TOKEN}@${HOST}:5432/${SCRATCH}?sslmode=require"
  trap 'python - "$APP_URL" "$SCRATCH" <<PYEOF2
import sys, psycopg
try:
    with psycopg.connect(sys.argv[1], autocommit=True) as c:
        c.execute(f"DROP DATABASE IF EXISTS \"{sys.argv[2]}\"")
except Exception as e:
    print(f"cleanup warning: {e}", file=sys.stderr)
PYEOF2' EXIT
  python - "$APP_URL" "$SCRATCH" <<'PYEOF'
import sys, psycopg
with psycopg.connect(sys.argv[1], autocommit=True) as c:
    c.execute(f'CREATE DATABASE "{sys.argv[2]}" TEMPLATE template0')
PYEOF
  command -v cygpath >/dev/null 2>&1 && DESIRED=$(cygpath -m "$DESIRED")  # Windows: file:// URLs need native paths
  SCHEMAS="$(lb_schema_args | awk '{print $2}' | paste -sd,)"
  # --exclude: legacy/ledger leftovers the drift probe already ignores
  # (schema_migrations table, grant_* legacy rbac helpers).
  python scripts/apply_desired.py \
    --url "$APP_URL" \
    --desired "$DESIRED" \
    --dev-url "$DEV_URL" \
    --atlas-bin "$ATLAS_BIN" \
    --schemas "$SCHEMAS" \
    --exclude "public.schema_migrations,public.grant_*" \
    || { echo "✗ declarative apply failed"; exit 2; }
  echo "  ✓ branch converged to desired state (declarative; no migration needed)"
else

echo "▶ 1/3 migrations (Atlas-native apply, exactly-once, atlas.sum + revision checksums)"
if [ -n "${SKIP_MIGRATIONS:-}" ]; then
  echo "  skipped (SKIP_MIGRATIONS=1 — migrations were applied by the official Atlas action)"
else
  ATLAS_BIN="${ATLAS_BIN:-atlas}" ./scripts/apply_migrations_atlas.sh "${HOST}" "${DATABRICKS_PG_USER}" "${TOKEN}"
fi

echo "▶ 2/3 objects (idempotent replay)"
_rc=0
python scripts/apply_objects.py \
  --host "${HOST}" --port 5432 --dbname databricks_postgres \
  --user "${DATABRICKS_PG_USER}" --password "${TOKEN}" \
  --sslmode require --objects-root db/objects || _rc=$?
if [ "$_rc" = 3 ]; then
  # ghosts were retired interactively; run once more to apply + record them
  echo "▶ 2/3 objects (re-run after interactive retirement)"
  python scripts/apply_objects.py \
    --host "${HOST}" --port 5432 --dbname databricks_postgres \
    --user "${DATABRICKS_PG_USER}" --password "${TOKEN}" \
    --sslmode require --objects-root db/objects
elif [ "$_rc" != 0 ]; then
  exit "$_rc"
fi

fi   # end CE/versioned track (see Pro declarative apply above)

if [ "${SKIP_TESTS:-}" = 1 ]; then
  echo "▶ SKIP_TESTS=1 — tests skipped"
elif [ -d db/tests ]; then
  # TEST_SUITE: smoke (read-only, safe for production CD) | all (smoke +
  # integration; integration writes data, dev/PR branches only). Default
  # smoke: CD must never run data-writing tests against production.
  SUITE="${TEST_SUITE:-smoke}"
  echo "▶ tests (suite: ${SUITE})"
  if [ "$SUITE" = "all" ] && [ "$TARGET_BRANCH" = "production" ]; then
    echo "✗ TEST_SUITE=all is refused against production: integration tests write data." >&2
    exit 1
  fi
  if [ "$SUITE" = "all" ]; then
    PGHOST="${HOST}" PGUSER="${DATABRICKS_PG_USER}" PGPASSWORD="${TOKEN}" \
      python -m pytest db/tests -q
  else
    PGHOST="${HOST}" PGUSER="${DATABRICKS_PG_USER}" PGPASSWORD="${TOKEN}" \
      python -m pytest db/tests/smoke -q
  fi
else
  echo "▶ no db/tests directory — skipped"
fi

echo "✅ deployed to ${TARGET_BRANCH}"
